INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'ZemplerBank','$source = \"Zempler Bank\"\n$features = \"REVERSE_ORDER\"\n$periodBufferDays = 5\n\n// Get account name (the personal name above Business Account)\n$accountName = get line starting \"Stephen Walton\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number:\" => skip words 2 => get text\n\n// Get period from/to\n@periodLine = get line containing \"From\" => take last words 7\n$periodFrom = take words @periodLine 3 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @periodLine 3 => get date \"dd/MM/yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Opening Balance:\" => skip words 2 => get decimal\n$closingBalance = get line starting \"Closing Balance:\" => skip words 2 => get decimal\n\n// Discard footer\nget line starting \"Zempler Bank Ltd is registered\" => top => ignore footer below\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Card ending in Description\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get last line starting \"Zempler Bank Ltd is registered\" => top => get line above\n\n// Discard repeating page headers\nget last line containing \"Date Card ending in Description\" => bottom => ignore header above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 160 430 510 page.right => describe table false \"*Date[dd/MM/yyyy]\" CardEnding Details #Amount #Balance','2024-01-01 00:00:00',0);
INSERT INTO `digitalpdf$documentidentification` (`Id`,`Name`,`TitlePattern`,`AuthorPattern`,`CreatorPattern`,`ProducerPattern`,`Version`,`PageCount`,`SignatureInfo`,`ContainsText`,`ExcludesText`,`ScriptId`,`VerificationRuleSetId`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'ZemplerBank',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[\"Zempler Bank\",\"Opening Balance:\",\"Closing Balance:\",\"Card ending in\"]',NULL,9999,4,'2024-01-01 00:00:00',0);